// Model output (structured), one confidence per field
var extraction = new Extraction(
    DocType: "receipt",
    Fields: new Dictionary<string, Field> {
        ["supplier"] = new("Hill & Co", 0.97),
        ["date"]     = new("2025-02-11", 0.93),
        ["total"]    = new("48.20",     0.71),
    },
    LineItemsSum: "46.20");

// Thresholds calibrated on a labelled validation set, per doc type and field
var Thresholds = new Dictionary<(string, string), double> { [("receipt", "supplier")] = 0.90, [("receipt", "date")] = 0.95,
    [("receipt", "total")] = 0.92, [("invoice", "total")] = 0.85 };

object Route(Extraction ex)
{
    var review = ex.Fields.Where(kv => kv.Value.Confidence < Thresholds[(ex.DocType, kv.Key)])
                          .Select(kv => kv.Key).ToList();
    if (ex.LineItemsSum != ex.Fields["total"].Value)
        review.Add("total (contradiction)");
    return review.Count > 0 ? review : "auto";   // a stratified sample of 'auto' still goes to QA
}

Console.WriteLine(JsonSerializer.Serialize(Route(extraction)));  // ["date","total","total (contradiction)"]

