// Model output (structured), one confidence per field
const extraction = {
  doc_type: "receipt",
  fields: {
    supplier: { value: "Hill & Co", confidence: 0.97 },
    date:     { value: "2025-02-11", confidence: 0.93 },
    total:    { value: "48.20",     confidence: 0.71 },
  },
  line_items_sum: "46.20",
};

// Thresholds calibrated on a labelled validation set, per doc type and field
const THRESHOLDS: Record<string, number> = { "receipt:supplier": 0.90, "receipt:date": 0.95,
  "receipt:total": 0.92, "invoice:total": 0.85 };

function route(ex: typeof extraction): string[] | "auto" {
  const review = Object.entries(ex.fields)
    .filter(([f, v]) => v.confidence < THRESHOLDS[`${ex.doc_type}:${f}`])
    .map(([f]) => f);
  if (ex.line_items_sum !== ex.fields.total.value) {
    review.push("total (contradiction)");
  }
  return review.length ? review : "auto";   // a stratified sample of 'auto' still goes to QA
}

console.log(route(extraction));  // ['date', 'total', 'total (contradiction)']

